// energy/degradation sketch for: Factory Layout Evolution Engine
let c = 1.0; const samples = [];
for (let i = 0; i < 430; i++) { c *= 0.9997; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 430, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

